# Multipliers that turn a pay rate into an annual salary (matches core.job_sources.ANNUAL).
ANNUAL = {"year": 1, "month": 12, "week": 52, "day": 260, "hour": 2080}


def parse_pay(text):
    """'$129k–$172k', '$50–$60/hour' or '125K–175K a year' -> annual (min, max)."""
    amounts = [float(n.replace(",", "")) * (1000 if k else 1)
               for n, k in re.findall(r"([\d][\d,.]*)\s*([kK])?", text)][:2]
    if not amounts:
        return None, None
    period = re.search(r"(year|month|week|day|hour)", text, re.IGNORECASE)
    rate = ANNUAL[period.group(1).lower()] if period else 1
    low, high = amounts[0] * rate, (amounts[1] * rate if len(amounts) > 1 else None)
    return round(low), round(high) if high else None


